mapper.sql:
WHERE c.status = 'PUBLISHED'

    AND c.type = #{type}


    AND EXISTS (
        SELECT 1 FROM content_category cc
        WHERE cc.content_id = c.id AND cc.category_id = #{categoryId}
    )


    AND EXISTS (
        SELECT 1 FROM content_tag ct
        WHERE ct.content_id = c.id AND ct.tag_id = #{tagId}
    )

WHERE 1 = 1

    AND c.type = #{type}


    AND c.status = #{status}


    AND EXISTS (
        SELECT 1 FROM content_category cc
        WHERE cc.content_id = c.id AND cc.category_id = #{categoryId}
    )


    AND EXISTS (
        SELECT 1 FROM content_tag ct
        WHERE ct.content_id = c.id AND ct.tag_id = #{tagId}
    )

mapper.select:
SELECT 
FROM contents c


LIMIT #{size} OFFSET #{offset}

SELECT 
FROM contents c
WHERE c.status = 'PUBLISHED'
  AND c.id != #{id}
  AND (
      c.published_at < #{publishedAt}
      OR (c.published_at = #{publishedAt} AND c.id < #{id})
  )
ORDER BY c.published_at DESC, c.id DESC
LIMIT 1

SELECT 
FROM contents c
WHERE c.status = 'PUBLISHED'
  AND c.id != #{id}
  AND (
      c.published_at > #{publishedAt}
      OR (c.published_at = #{publishedAt} AND c.id > #{id})
  )
ORDER BY c.published_at ASC, c.id ASC
LIMIT 1

SELECT 
FROM contents c


LIMIT #{size} OFFSET #{offset}

SELECT 
FROM contents c
WHERE c.id = #{id}

SELECT COUNT(*)
FROM contents
WHERE slug = #{slug}

    AND id != #{excludeId}
